CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS college_students(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),enrollment_no text NOT NULL,first_name text NOT NULL,last_name text NOT NULL,phone text,email text,user_id uuid REFERENCES users(id),status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,enrollment_no));
CREATE TABLE IF NOT EXISTS college_faculty(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES users(id),employee_no text NOT NULL,name text NOT NULL,department text,status text NOT NULL DEFAULT 'active',UNIQUE(tenant_id,employee_no));
CREATE TABLE IF NOT EXISTS college_departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,code text NOT NULL,status text NOT NULL DEFAULT 'active',UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS college_courses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),department_id uuid REFERENCES college_departments(id),code text NOT NULL,name text NOT NULL,credits int NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'active',UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS college_enrollments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),student_id uuid NOT NULL REFERENCES college_students(id),course_id uuid NOT NULL REFERENCES college_courses(id),semester text NOT NULL,status text NOT NULL DEFAULT 'active',UNIQUE(tenant_id,student_id,course_id,semester));
CREATE TABLE IF NOT EXISTS college_attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),student_id uuid NOT NULL REFERENCES college_students(id),course_id uuid NOT NULL REFERENCES college_courses(id),attendance_date date NOT NULL,status text NOT NULL CHECK(status IN ('present','absent','late','excused')),marked_by uuid REFERENCES users(id),UNIQUE(tenant_id,student_id,course_id,attendance_date));
CREATE TABLE IF NOT EXISTS college_fees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),student_id uuid NOT NULL REFERENCES college_students(id),amount numeric(14,2) NOT NULL CHECK(amount>=0),due_date date NOT NULL,status text NOT NULL DEFAULT 'pending',paid_at timestamptz,payment_reference text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS college_exams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),course_id uuid NOT NULL REFERENCES college_courses(id),name text NOT NULL,exam_date date NOT NULL,max_marks numeric(8,2) NOT NULL,status text NOT NULL DEFAULT 'scheduled');
CREATE TABLE IF NOT EXISTS college_exam_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),exam_id uuid NOT NULL REFERENCES college_exams(id),student_id uuid NOT NULL REFERENCES college_students(id),marks numeric(8,2) NOT NULL CHECK(marks>=0),grade text,UNIQUE(tenant_id,exam_id,student_id));
CREATE INDEX IF NOT EXISTS idx_college_students_tenant ON college_students(tenant_id); CREATE INDEX IF NOT EXISTS idx_college_attendance_tenant_date ON college_attendance(tenant_id,attendance_date); CREATE INDEX IF NOT EXISTS idx_college_fees_tenant_student ON college_fees(tenant_id,student_id);